SCHEMA = {
    "required": ["name", "priority"],
    "types": {"name": str, "priority": int},
}

RECORDS = [
    ("record_1", {"name": "reset password", "priority": 2}),
    ("record_2", {"name": "billing question"}),
    ("record_3", {"name": "api outage", "priority": "high"}),
]

def validate(record, schema):
    errors = []
    for field in schema["required"]:
        if field not in record:
            errors.append(f"missing {field}")
        elif not isinstance(record[field], schema["types"][field]):
            errors.append(f"wrong type {field}")
    return errors

valid_count = 0
for name, record in RECORDS:
    errors = validate(record, SCHEMA)
    if errors:
        print(f"{name}: {'; '.join(errors)}")
    else:
        valid_count += 1
        print(f"{name}: valid")
print(f"valid_count={valid_count}")
